//! Rust port of `tests/test4.cpp`.
//!
//! Prints, one per line, the results of the four `idna` predicates applied to
//! the domain given as the first command-line argument (defaulting to
//! `example.com`).
//!
//! The library modules are pulled in by path so that this file builds both as
//! the Cargo `test4` binary and standalone via `rustc test4.rs`.

#[path = "src/idna/mod.rs"]
mod idna;

fn main() {
    if let Err(err) = idna::cli::run() {
        // A broken pipe on stdout is not worth a panic.
        eprintln!("test4: {err}");
        std::process::exit(1);
    }
}

#include <iostream>
#include <string>
#include "../idna.hpp"

int main(int argc, char* argv[]) {
    std::string input = "example.com";
    if (argc > 1) {
        input = argv[1];
    }

    bool valid_domain = idna::is_valid_domain(input);
    bool valid_label = idna::is_valid_label(input);
    bool is_ascii = idna::is_ascii_domain(input);
    bool is_idn = idna::is_idn_domain(input);

    std::cout << valid_domain << std::endl;
    std::cout << valid_label << std::endl;
    std::cout << is_ascii << std::endl;
    std::cout << is_idn << std::endl;

    return 0;
}


