//! Zero-dependency Rust reimplementation of the `idna` C++ library surface
//! exercised by `tests/test4.cpp`.
//!
//! The four predicates re-exported from [`idna`] mirror the reference C++
//! implementation bit-for-bit, including its quirks (see [`idna::validate`]).

pub mod idna;
===== /output/src/idna/limits.rs =====
//! Size limits enforced by the reference implementation.
//!
//! Both limits are measured in **bytes**, not Unicode scalar values. This was
//! established by bisecting the reference binary with multi-byte input:
//!
//! | input           | bytes | code points | `is_valid_label` |
//! |-----------------|-------|-------------|------------------|
//! | `"例"` x 21     | 63    | 21          | 1                |
//! | `"例"` x 22     | 66    | 22          | 0                |
//! | `"例"` x 63     | 189   | 63          | 0                |
//! | `"ü"` x 31      | 62    | 31          | 1                |
//! | `"ü"` x 32      | 64    | 32          | 0                |
//! | `"😀"` x 15     | 60    | 15          | 1                |
//! | `"😀"` x 16     | 64    | 16          | 0                |
//!
//! A 63-code-point / 189-byte label is rejected while a 21-code-point /
//! 63-byte label is accepted, so the cutoff tracks bytes.

/// Maximum length, in bytes, of a single DNS label.
pub const MAX_LABEL_LEN: usize = 63;

/// Maximum length, in bytes, of a whole domain name.
///
/// Note this is 255, not the 253 that a strict reading of RFC 1035 would give
/// for a presentation-format name. The reference implementation compares
/// against the 255-octet wire limit directly: a 255-byte input is accepted and
/// a 256-byte input is rejected.
pub const MAX_DOMAIN_LEN: usize = 255;

/// Largest byte value considered ASCII.
pub const MAX_ASCII_BYTE: u8 = 0x7F;
===== /output/src/idna/mod.rs =====
//! The `idna` namespace: domain-name predicates.
//!
//! Every predicate operates on raw bytes rather than on `str`. The reference
//! C++ implementation takes a `std::string`, which is a byte container with no
//! encoding guarantees, and its length checks count *bytes*. Mirroring that
//! with `[u8]` keeps the Rust port faithful for inputs that are not valid
//! UTF-8 -- the C++ binary accepts a lone `0xFF` argument without complaint.

pub mod ascii;
pub mod cli;
pub mod limits;
pub mod validate;

// `self::` is redundant under edition 2021 but keeps a bare `rustc test4.rs`
// -- which defaults to edition 2015 -- working too.
pub use self::ascii::{is_ascii_domain, is_idn_domain};
pub use self::validate::{is_valid_domain, is_valid_label};
===== /output/src/idna/cli.rs =====
//! Command-line front end, mirroring `tests/test4.cpp`.

use std::ffi::OsString;
use std::io::{self, Write};

use super::{is_ascii_domain, is_idn_domain, is_valid_domain, is_valid_label};

/// Value used when no domain is supplied on the command line.
pub const DEFAULT_INPUT: &str = "example.com";

/// Reads the domain to test from the process arguments.
///
/// Mirrors `if (argc > 1) input = argv[1];` -- the first argument is used when
/// present, any further arguments are ignored, and an explicitly empty first
/// argument is honoured (yielding the empty string, not the default).
///
/// This deliberately goes through [`std::env::args_os`] rather than
/// [`std::env::args`]. `args` panics on an argument that is not valid UTF-8,
/// whereas the C++ binary happily accepts one -- a lone `0xFF` byte prints
/// `1 1 0 1`. Since `std::string` imposes no encoding, staying in the byte
/// domain is what actually reproduces the reference behaviour.
pub fn input_from_args() -> Vec<u8> {
    match std::env::args_os().nth(1) {
        Some(arg) => into_bytes(arg),
        None => DEFAULT_INPUT.as_bytes().to_vec(),
    }
}

#[cfg(unix)]
fn into_bytes(arg: OsString) -> Vec<u8> {
    use std::os::unix::ffi::OsStringExt;
    arg.into_vec()
}

#[cfg(not(unix))]
fn into_bytes(arg: OsString) -> Vec<u8> {
    // No lossless `OsString` -> bytes conversion exists off Unix. Arguments
    // there are UTF-16-ish, so this is the closest available approximation.
    arg.to_string_lossy().into_owned().into_bytes()
}

/// Formats the four predicate results exactly as the C++ program prints them.
///
/// Each line is a single `1` or `0` followed by `\n`; a bare `std::cout << bool`
/// uses numeric rather than `boolalpha` formatting, and `std::endl` emits `\n`
/// (never `\r\n`). A typical run therefore writes exactly 8 bytes.
pub fn render(input: &[u8]) -> String {
    let results = [
        is_valid_domain(input),
        is_valid_label(input),
        is_ascii_domain(input),
        is_idn_domain(input),
    ];

    let mut out = String::with_capacity(results.len() * 2);
    for flag in results {
        out.push(if flag { '1' } else { '0' });
        out.push('\n');
    }
    out
}

/// Runs the program: read the argument, print the four flags.
pub fn run() -> io::Result<()> {
    let input = input_from_args();
    let mut stdout = io::stdout().lock();
    stdout.write_all(render(&input).as_bytes())?;
    // `std::endl` flushes; do the same so output ordering is identical when
    // stdout is a pipe.
    stdout.flush()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn default_input_matches_the_cpp_literal() {
        assert_eq!(render(DEFAULT_INPUT.as_bytes()), "1\n1\n1\n0\n");
    }

    #[test]
    fn documented_examples() {
        for domain in [
            "example.com",
            "test.org",
            "subdomain.example.com",
            "deep.nested.subdomain.example.com",
        ] {
            assert_eq!(render(domain.as_bytes()), "1\n1\n1\n0\n", "{domain}");
        }
        assert_eq!(render("例子.测试".as_bytes()), "1\n1\n0\n1\n");
    }

    #[test]
    fn empty_input() {
        assert_eq!(render(b""), "0\n0\n1\n0\n");
    }

    #[test]
    fn output_is_eight_bytes() {
        assert_eq!(render(b"example.com").len(), 8);
    }

    #[test]
    fn invalid_utf8_is_accepted_and_reported_as_idn() {
        assert_eq!(render(b"\xff"), "1\n1\n0\n1\n");
        assert_eq!(render(b"\xc3"), "1\n1\n0\n1\n");
        assert_eq!(render(b"ab\xffcd.com"), "1\n1\n0\n1\n");
    }
}
